INSERT INTO cfg.indicator (id, name, unit, how_to_measure, why_it_matters, source_id, display_order) VALUES
  ('glucose', 'Blood glucose', 'mg/dL', 'With a glucometer or a continuous glucose monitor. A continuous monitor flew on Ax-4 in 2025.', 'Glucose is the sugar in your blood. A value outside the normal range can be a sign of abnormal glucose regulation.', 'inspiration4_metabolic_panel', 1),
  ('heart_rate', 'Heart rate', 'bpm', 'With a wearable ECG or a smartwatch, all day. On the ISS, the Bio-Monitor shirt does it.', 'How many times your heart beats each minute. A heart rate that stays high at rest can point to dehydration, infection, stress or a cardiovascular problem.', 'lifesnaps', 2),
  ('resting_heart_rate', 'Resting heart rate', 'bpm', 'A wrist tracker or smartwatch works it out once a day from your heart rate while you are still. On the ISS, the Bio-Monitor shirt (CSA) records heart rate.', 'Your heart rate when you are at rest. If it stays above your usual value, it can point to dehydration, infection, stress or a cardiovascular problem.', 'lifesnaps', 3),
  ('very_active_minutes', 'Very active minutes', 'min', 'A wrist tracker counts the minutes of intense activity each day. On a mission, the exercise sessions are also logged on the tablet.', 'Exercise is the main countermeasure against bone and muscle loss in space. This counts general intense activity, not only resistance exercise.', 'lifesnaps', 4),
  ('steps', 'Steps', 'steps', 'A wrist tracker counts them each day.', 'A simple measure of how much you move each day. In microgravity nobody walks, so on a mission the exercise log would take its place.', 'lifesnaps', 5),
  ('sleep_duration', 'Sleep duration', 'min', 'A wrist tracker measures it every night. On the ISS, astronauts wear NASA''s Actiwatch for it.', 'How long you were asleep, not how long you were in bed. Too little sleep, night after night, lowers attention and mood.', 'lifesnaps', 6),
  ('sleep_efficiency', 'Sleep efficiency', '%', 'A wrist tracker measures it every night, together with sleep duration.', 'The share of your time in bed that you spent asleep. A low value means broken sleep, even when you were in bed long enough.', 'lifesnaps', 7),
  ('skin_temperature', 'Skin temperature', '°C', 'A wrist tracker measures it during the night. On the ISS, the Bio-Monitor shirt also measures skin temperature.', 'A rise from your usual value, together with symptoms, can be an early sign of infection. Skin temperature is lower than core body temperature, so compare it only with your own values.', 'lifesnaps', 8),
  ('minutes_awake', 'Time awake in bed', 'min', 'A wrist tracker measures it every night, together with sleep duration.', 'The minutes you spent awake between falling asleep and getting up. Waking often breaks sleep even when the total time in bed looks long enough.', 'lifesnaps', 9),
  ('spo2', 'Blood oxygen (SpO2)', '%', 'A pulse oximeter or a wrist tracker, here measured during the night. On the ISS, the Bio-Monitor shirt measures it.', 'How much of your blood''s haemoglobin carries oxygen. A value falling from your usual one can be an early sign of a breathing or circulation problem.', 'lifesnaps', 10),
  ('breathing_rate', 'Breathing rate', 'breaths/min', 'A wrist tracker estimates it while you sleep. On the ISS, the Bio-Monitor shirt measures it.', 'How many breaths you take each minute at rest. A clear change from your usual value can point to an infection, stress or a breathing problem.', 'lifesnaps', 11),
  ('mood_happy', 'Happy', NULL, 'In the daily check-in on the tablet.', 'One of the six moods of the daily check-in. A change in the moods you report over time can be a sign of a behavioural change. It is not a diagnosis.', 'lifesnaps', 12),
  ('mood_sad', 'Sad', NULL, 'In the daily check-in on the tablet.', 'One of the six moods of the daily check-in. A change in the moods you report over time can be a sign of a behavioural change. It is not a diagnosis.', 'lifesnaps', 13),
  ('mood_tense', 'Tense or anxious', NULL, 'In the daily check-in on the tablet.', 'One of the six moods of the daily check-in. A change in the moods you report over time can be a sign of a behavioural change. It is not a diagnosis.', 'lifesnaps', 14),
  ('mood_alert', 'Alert', NULL, 'In the daily check-in on the tablet.', 'One of the six moods of the daily check-in. A change in the moods you report over time can be a sign of a behavioural change. It is not a diagnosis.', 'lifesnaps', 15),
  ('mood_rested', 'Rested or relaxed', NULL, 'In the daily check-in on the tablet.', 'One of the six moods of the daily check-in. A change in the moods you report over time can be a sign of a behavioural change. It is not a diagnosis.', 'lifesnaps', 16),
  ('mood_neutral', 'Neutral', NULL, 'In the daily check-in on the tablet.', 'One of the six moods of the daily check-in. A change in the moods you report over time can be a sign of a behavioural change. It is not a diagnosis.', 'lifesnaps', 17),
  ('mood_sad_days_14', 'Sad days in the last 14', 'days', 'Counted from your daily check-ins. A day with no check-in counts as not chosen.', 'A mood that stays for most of two weeks is worth a conversation. This is a count of your own check-ins, not a questionnaire and not a diagnosis.', 'lifesnaps', 18),
  ('mood_tense_days_14', 'Tense or anxious days in the last 14', 'days', 'Counted from your daily check-ins. A day with no check-in counts as not chosen.', 'A mood that stays for most of two weeks is worth a conversation. This is a count of your own check-ins, not a questionnaire and not a diagnosis.', 'lifesnaps', 19);
